bicepWiring.resource:
resource communicationService 'Microsoft.Communication/communicationServices@2023-04-01' = {
  name: communicationServiceName
  location: 'global'
  properties: { dataLocation: dataLocation }
}

bicepWiring.emailService:
resource emailService 'Microsoft.Communication/emailServices@2023-04-01' = {
  name: '${communicationServiceName}-email'
  location: 'global'
  properties: { dataLocation: dataLocation }
}

resource emailDomain 'Microsoft.Communication/emailServices/domains@2023-04-01' = {
  parent: emailService
  name: 'AzureManagedDomain'
  location: 'global'
  properties: { domainManagement: 'AzureManaged' }
}

bicepWiring.linkEmailToCommunication:
resource emailLink 'Microsoft.Communication/communicationServices/domains@2023-04-01' = {
  // Link is done via communicationService properties.linkedDomains array
}

sdkInitPattern.typescript:
import { EmailClient } from '@azure/communication-email';
import { DefaultAzureCredential } from '@azure/identity';

const credential = new DefaultAzureCredential();
const client = new EmailClient(process.env.AZURE_COMMUNICATION_ENDPOINT!, credential);

const poller = await client.beginSend({
  senderAddress: process.env.AZURE_EMAIL_SENDER!,
  recipients: { to: [{ address: recipient }] },
  content: { subject, plainText: body }
});
const result = await poller.pollUntilDone();
